const rebalancingLinksForPlan = `-- name: RebalancingLinksForPlan :many
SELECT id, action_plan_id, rebalancing_plan_id, created_at FROM tax_action_rebalancing_plans WHERE action_plan_id = $1 ORDER BY created_at ASC
`

func (q *Queries) RebalancingLinksForPlan(ctx context.Context, actionPlanID uuid.UUID) ([]TaxActionRebalancingPlan, error) {
	rows, err := q.db.Query(ctx, rebalancingLinksForPlan, actionPlanID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TaxActionRebalancingPlan{}
	for rows.Next() {
		var i TaxActionRebalancingPlan
		if err := rows.Scan(
			&i.ID,
			&i.ActionPlanID,
			&i.RebalancingPlanID,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

